# Let's solve the 4-queens problem using backtracking
def solve_4queens():
    n = 4
    # board[i] = column of queen in row i
    board = [-1] * n

    def is_safe(row, col):
        for r in range(row):
            c = board[r]
            if c == col:  # same column
                return False
            if abs(r - row) == abs(c - col):  # same diagonal
                return False
        return True

    def backtrack(row):
        if row == n:
            return True
        for col in range(n):
            if is_safe(row, col):
                board[row] = col
                if backtrack(row + 1):
                    return True
                board[row] = -1
        return False

    if backtrack(0):
        return board
    return None

solution = solve_4queens()
print(solution)

def verify(board):
    n = len(board)
    for i in range(n):
        for j in range(i+1, n):
            if board[i] == board[j]:
                return False, f"Same column: rows {i} and {j}"
            if abs(i-j) == abs(board[i]-board[j]):
                return False, f"Same diagonal: rows {i} and {j}"
    return True, "Valid"

print(verify([1, 3, 0, 2]))

